// ---------------------------------------------------------------------------------------------
// Normalization (see hack/golden/controller/main.go)
// ---------------------------------------------------------------------------------------------

fn is_empty(v: &Value) -> bool {
    match v {
        Value::Null => true,
        Value::Object(m) => m.is_empty(),
        Value::Array(a) => a.is_empty(),
        _ => false,
    }
}

fn normalize_value(v: Value) -> Value {
    match v {
        Value::Object(m) => {
            let mut out = Map::new();
            for (k, val) in m {
                if k == "lastTransitionTime" {
                    continue;
                }
                let n = normalize_value(val);
                if is_empty(&n) {
                    continue;
                }
                out.insert(k, n);
            }
            Value::Object(out)
        }
        Value::Array(a) => Value::Array(a.into_iter().map(normalize_value).collect()),
        other => other,
    }
}

fn normalize_object(kind: &str, mut v: Value) -> Value {
    let name = v["metadata"]["name"]
        .as_str()
        .unwrap_or_default()
        .to_string();
    match kind {
        "HostedCluster" => {
            if let Some(infra) = v["spec"]["infraID"].as_str().filter(|s| !s.is_empty()) {
                let suffix = infra
                    .strip_prefix(&format!("{name}-"))
                    .unwrap_or_else(|| panic!("unexpected infraID {infra}"));
                assert!(
                    suffix.len() == 5 && suffix.chars().all(|c| INFRA_ALPHABET.contains(c)),
                    "unexpected infraID {infra}"
                );
                v["spec"]["infraID"] = Value::String("INFRAID".into());
            }
        }
        "Secret" if name.ends_with("-etcd-encryption-key") => {
            let key = v["data"][hyperv1::AESCBC_KEY_SECRET_KEY]
                .as_str()
                .expect("etcd key");
            let raw = base64::engine::general_purpose::STANDARD
                .decode(key)
                .unwrap();
            assert_eq!(raw.len(), 32, "unexpected etcd key length");
            v["data"][hyperv1::AESCBC_KEY_SECRET_KEY] =
                Value::String(base64::engine::general_purpose::STANDARD.encode(b"KEY"));
        }
        _ => {}
    }
    if let Value::Object(m) = &mut v {
        m.remove("apiVersion");
        m.remove("kind");
        if let Some(Value::Object(md)) = m.get_mut("metadata") {
            for k in [
                "resourceVersion",
                "creationTimestamp",
                "deletionTimestamp",
                "managedFields",
            ] {
                md.remove(k);
            }
        }
    }
    normalize_value(v)
}

