#[derive(Debug, Clone, PartialEq)]
struct Action {
    verb: String,
    kind: String,
    namespace: String,
    name: String,
    object: Option<Value>,
}

struct Env {
    client: Client,
    recorder: Arc<FakeRecorder>,
    actions: Arc<Mutex<Vec<Action>>>,
    recording: Arc<AtomicBool>,
    r: DPFHCPProvisionerReconciler,
}

/// fakeImageChecker implements bfocplookup.ImageChecker (the tag always exists).
struct FakeImageChecker;

#[async_trait::async_trait]
impl ctrl_bfocplookup::ImageChecker for FakeImageChecker {
    async fn check_tag(
        &self,
        _ctx: &Ctx,
        _r: &registry::name::Reference,
        _keychain: Arc<dyn registry::authn::Keychain>,
    ) -> ctrlrt::Result<()> {
        Ok(())
    }
}

fn scheme() -> Scheme {
    Scheme::new()
        .with_client_go()
        .register::<provisioningv1alpha1::DPFHCPProvisioner>()
        .register::<provisioningv1alpha1::DPFHCPProvisionerConfig>()
        .register::<dpuprovisioningv1alpha1::DPUCluster>()
        .register::<dpuprovisioningv1alpha1::DPUFlavor>()
        .register::<dpuservicev1alpha1::DPUDeployment>()
        .register::<dpuservicev1alpha1::DPUServiceTemplate>()
        .register::<operatorv1alpha1::DPFOperatorConfig>()
        .register::<hyperv1::HostedCluster>()
        .register::<hyperv1::NodePool>()
        .register::<metallbv1beta1::IPAddressPool>()
        .register::<metallbv1beta1::L2Advertisement>()
}

fn new_env(objs: Vec<InitObject>) -> Env {
    let actions: Arc<Mutex<Vec<Action>>> = Arc::default();
    let recording = Arc::new(AtomicBool::new(false));
    let (rec_actions, rec_on) = (actions.clone(), recording.clone());
    let c = FakeClientBuilder::new()
        .with_scheme(scheme())
        .with_objects(objs)
        .with_status_subresource::<provisioningv1alpha1::DPFHCPProvisioner>()
        .with_status_subresource::<dpuprovisioningv1alpha1::DPUCluster>()
        .with_status_subresource::<hyperv1::HostedCluster>()
        .with_status_subresource::<hyperv1::NodePool>()
        .with_reactor("*", "*", move |a| {
            if rec_on.load(Ordering::SeqCst)
                && matches!(a.verb.as_str(), "create" | "update" | "delete")
            {
                let verb = if a.subresource.is_empty() {
                    a.verb.clone()
                } else {
                    format!("{}-{}", a.verb, a.subresource)
                };
                let object = match &a.object {
                    Some(v) if a.verb != "delete" => {
                        Some(normalize_object(&a.info.kind, v.clone()))
                    }
                    _ => None,
                };
                rec_actions.lock().unwrap().push(Action {
                    verb,
                    kind: a.info.kind.clone(),
                    namespace: a.namespace.clone(),
                    name: a.name.clone(),
                    object,
                });
            }
            Reaction::NotHandled
        })
        .build();
    let recorder = Arc::new(FakeRecorder::new(1000));
    let rec: Recorder = recorder.clone();

    // Wiring of cmd/main.go (one shared recorder).
    let mut image_lookup = ctrl_bfocplookup::ImageLookup::new(c.clone(), rec.clone());
    image_lookup.image_checker = Arc::new(FakeImageChecker);
    let hosted_client_manager = Arc::new(hostedclient::ClientManager::new(c.clone()));
    let mut finalizer_manager = ctrl_finalizer::Manager::new(c.clone(), rec.clone());
    finalizer_manager.register_handler(ctrl_kubeconfiginjection::CleanupHandler::new(
        c.clone(),
        rec.clone(),
    ));
    finalizer_manager.register_handler(ctrl_hostedcluster::CleanupHandler::new(
        c.clone(),
        rec.clone(),
    ));
    finalizer_manager.register_handler(ctrl_metallb::CleanupHandler::new(c.clone(), rec.clone()));
    let r = DPFHCPProvisionerReconciler {
        client: c.clone(),
        recorder: rec.clone(),
        image_lookup: Some(Arc::new(image_lookup)),
        dpu_cluster_validator: Some(Arc::new(ctrl_dpucluster::Validator::new(
            c.clone(),
            rec.clone(),
        ))),
        secrets_validator: Some(Arc::new(ctrl_secrets::Validator::new(
            c.clone(),
            rec.clone(),
        ))),
        secret_manager: Some(Arc::new(ctrl_hostedcluster::SecretManager::new(c.clone()))),
        metal_lb_manager: Some(Arc::new(ctrl_metallb::MetalLBManager::new(
            c.clone(),
            rec.clone(),
        ))),
        hosted_cluster_manager: Some(Arc::new(ctrl_hostedcluster::HostedClusterManager::new(
            c.clone(),
        ))),
        node_pool_manager: Some(Arc::new(ctrl_hostedcluster::NodePoolManager::new(
            c.clone(),
        ))),
        finalizer_manager: Some(Arc::new(finalizer_manager)),
        status_syncer: Some(Arc::new(ctrl_hostedcluster::StatusSyncer::new(c.clone()))),
        kubeconfig_injector: Some(Arc::new(ctrl_kubeconfiginjection::KubeconfigInjector::new(
            c.clone(),
            rec.clone(),
        ))),
        ignition_generator: Some(Arc::new(ctrl_ignitiongenerator::IgnitionGenerator::new(
            c.clone(),
            rec.clone(),
        ))),
        hugepages_manager: Some(Arc::new(ctrl_ovshugepages::Manager::new(
            c.clone(),
            hosted_client_manager,
            Arc::new(ctrl_dpuservicetemplate::RemoteReleaseImageReader),
        ))),
        ..Default::default()
    };
    Env {
        client: c,
        recorder,
        actions,
        recording,
        r,
    }
}

fn key() -> ObjectKey {
    ObjectKey::new(CR_NS, CR_NAME)
}

#[derive(Debug, PartialEq)]
struct Step {
    label: String,
    requeue: bool,
    requeue_after: String,
    error: String,
    actions: Vec<Action>,
    events: Vec<String>,
    exists: bool,
    status: Option<Value>,
    finalizers: Vec<String>,
}

impl Env {
    async fn reconcile(&self, label: &str, req: ObjectKey) -> Step {
        self.actions.lock().unwrap().clear();
        self.recording.store(true, Ordering::SeqCst);
        let res = self.r.reconcile(&Ctx::background(), req.clone()).await;
        self.recording.store(false, Ordering::SeqCst);
        let (result, error) = match res {
            Ok(r) => (r, String::new()),
            // Go: `return result, err` — the result travels with the error.
            Err(err) => (ctrlrt::result_of_error(&err), err.to_string()),
        };
        let mut step = Step {
            label: label.into(),
            requeue: result.requeue,
            requeue_after: GoDuration(result.requeue_after.as_nanos() as i64).to_string(),
            error,
            actions: self.actions.lock().unwrap().clone(),
            events: self.recorder.drain(),
            exists: false,
            status: None,
            finalizers: vec![],
        };
        if let Ok(cr) = self
            .client
            .get::<provisioningv1alpha1::DPFHCPProvisioner>(&req)
            .await
        {
            step.exists = true;
            step.status = Some(normalize_value(serde_json::to_value(&cr.status).unwrap()));
            step.finalizers = cr.metadata.finalizers.clone().unwrap_or_default();
        }
        step
    }

    // --- driver mutations (not recorded) ---------------------------------------------------

    async fn create<K: Object>(&self, mut o: K) {
        self.client.create(&mut o).await.unwrap();
    }

    async fn ensure<K: Object>(&self, mut o: K) {
        if let Err(e) = self.client.create(&mut o).await {
            assert!(ctrlrt::error::is_already_exists(&e), "{e}");
        }
    }

    async fn mutate_cr(&self, f: impl FnOnce(&mut provisioningv1alpha1::DPFHCPProvisioner)) {
        let mut cr: provisioningv1alpha1::DPFHCPProvisioner =
            self.client.get(&key()).await.unwrap();
        f(&mut cr);
        self.client.update(&mut cr).await.unwrap();
    }

    async fn mutate_cr_status(&self, f: impl FnOnce(&mut provisioningv1alpha1::DPFHCPProvisioner)) {
        let mut cr: provisioningv1alpha1::DPFHCPProvisioner =
            self.client.get(&key()).await.unwrap();
        f(&mut cr);
        self.client.update_status(&mut cr).await.unwrap();
    }

    async fn mutate_hc_status(&self, f: impl FnOnce(&mut hyperv1::HostedCluster)) {
        let mut hc: hyperv1::HostedCluster = self.client.get(&key()).await.unwrap();
        f(&mut hc);
        self.client.update_status(&mut hc).await.unwrap();
    }

    async fn mutate_dd(&self, f: impl FnOnce(&mut dpuservicev1alpha1::DPUDeployment)) {
        let mut dd: dpuservicev1alpha1::DPUDeployment = self
            .client
            .get(&ObjectKey::new(DPF_NS, DD_NAME))
            .await
            .unwrap();
        f(&mut dd);
        self.client.update(&mut dd).await.unwrap();
    }

    async fn delete<K: Object>(&self, o: K) {
        self.client.delete(&o).await.unwrap();
    }
}

