fn cond_now(type_: &str, status: &str, reason: &str, message: &str) -> Condition {
    let mut c = meta::condition(type_, status, reason, message);
    c.last_transition_time = meta::now();
    c
}

fn hc_conditions(available: &str) -> Vec<Condition> {
    vec![
        cond_now(
            hyperv1::HOSTED_CLUSTER_AVAILABLE,
            available,
            "AsExpected",
            "The hosted control plane is available",
        ),
        cond_now(
            hyperv1::HOSTED_CLUSTER_PROGRESSING,
            CONDITION_FALSE,
            "AsExpected",
            "HostedCluster is at expected version",
        ),
        cond_now(
            hyperv1::HOSTED_CLUSTER_DEGRADED,
            CONDITION_FALSE,
            "AsExpected",
            "",
        ),
    ]
}

fn history(entries: &[(&str, &str)]) -> Vec<hyperv1::ControlPlaneUpdateHistory> {
    entries
        .iter()
        .map(|(version, image)| hyperv1::ControlPlaneUpdateHistory {
            state: configv1::COMPLETED_UPDATE.into(),
            version: version.to_string(),
            image: image.to_string(),
            ..Default::default()
        })
        .collect()
}

fn set_cond(
    cr: &mut provisioningv1alpha1::DPFHCPProvisioner,
    t: &str,
    s: &str,
    reason: &str,
    msg: &str,
    generation: i64,
) {
    meta::set_status_condition(
        &mut cr.status.conditions,
        meta::condition_gen(t, s, reason, msg, generation),
    );
}

fn ignition_configured_true(cr: &mut provisioningv1alpha1::DPFHCPProvisioner) {
    let generation = cr.metadata.generation.unwrap_or(0);
    set_cond(
        cr,
        provisioningv1alpha1::IGNITION_CONFIGURED,
        CONDITION_TRUE,
        provisioningv1alpha1::REASON_IGNITION_GENERATED,
        "Ignition ConfigMap bfcfg-dpu.cfg created successfully",
        generation,
    );
}

fn ready_cr() -> provisioningv1alpha1::DPFHCPProvisioner {
    let mut cr = with_finalizer(base_cr());
    cr.status.phase = provisioningv1alpha1::PHASE_READY.into();
    cr.status.hosted_cluster_ref = Some(apis::k8s::core::v1::ObjectReference {
        name: CR_NAME.into(),
        namespace: CR_NS.into(),
        kind: "HostedCluster".into(),
        api_version: "hypershift.openshift.io/v1beta1".into(),
        ..Default::default()
    });
    set_cond(
        &mut cr,
        provisioningv1alpha1::HOSTED_CLUSTER_AVAILABLE,
        CONDITION_TRUE,
        "AsExpected",
        "The hosted control plane is available",
        0,
    );
    set_cond(
        &mut cr,
        provisioningv1alpha1::KUBE_CONFIG_INJECTED,
        CONDITION_TRUE,
        provisioningv1alpha1::REASON_KUBE_CONFIG_INJECTED,
        "Kubeconfig injected",
        0,
    );
    set_cond(
        &mut cr,
        provisioningv1alpha1::IGNITION_CONFIGURED,
        CONDITION_TRUE,
        provisioningv1alpha1::REASON_IGNITION_GENERATED,
        "Ignition ConfigMap bfcfg-dpu.cfg created successfully",
        1,
    );
    cr
}

