fn owned_hc(image: &str) -> hyperv1::HostedCluster {
    let mut hc = hyperv1::HostedCluster {
        metadata: ObjectMeta {
            owner_references: Some(owner_refs()),
            ..om(CR_NAME, CR_NS)
        },
        ..Default::default()
    };
    hc.spec.release.image = image.into();
    hc.spec.infra_id = "dpf-hcp-bcdfg".into();
    hc.spec.pull_secret.name = ctrl_hostedcluster::pull_secret_copy_name(&base_cr());
    hc.spec.ssh_key.name = ctrl_hostedcluster::ssh_key_copy_name(&base_cr());
    hc.status.conditions = hc_conditions(CONDITION_TRUE);
    hc.status.control_plane_version.history = history(&[("4.19.0", IMAGE_419)]);
    hc
}

fn ready_world(extra: Vec<InitObject>) -> Env {
    let mut objs = world();
    objs.extend([
        obj(&ready_cr()),
        obj(&owned_hc(IMAGE_419)),
        obj(&kubeconfig_secret()),
        obj(&ignition_cm("flavor-1", "bfb-1")),
    ]);
    objs.extend(extra);
    new_env(objs)
}

// ---------------------------------------------------------------------------------------------
// Comparison
// ---------------------------------------------------------------------------------------------

fn fixture(name: &str) -> Value {
    let path = format!("{}/tests/fixtures/{name}.json", env!("CARGO_MANIFEST_DIR"));
    let s = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    serde_json::from_str(&s).unwrap()
}

fn check(name: &str, steps: &[Step]) {
    let want = fixture(name);
    let want_steps = want["steps"].as_array().unwrap();
    assert_eq!(
        steps.iter().map(|s| s.label.as_str()).collect::<Vec<_>>(),
        want_steps
            .iter()
            .map(|s| s["label"].as_str().unwrap())
            .collect::<Vec<_>>(),
        "{name}: steps"
    );
    for (got, want) in steps.iter().zip(want_steps) {
        let ctx = format!("{name} / {}", got.label);
        assert_eq!(got.error, want["error"].as_str().unwrap(), "{ctx}: error");
        assert_eq!(
            got.requeue,
            want["requeue"].as_bool().unwrap(),
            "{ctx}: requeue"
        );
        assert_eq!(
            got.requeue_after,
            want["requeueAfter"].as_str().unwrap(),
            "{ctx}: requeueAfter"
        );
        let want_events: Vec<String> = serde_json::from_value(want["events"].clone()).unwrap();
        assert_eq!(got.events, want_events, "{ctx}: events");

        let want_actions = want["actions"].as_array().unwrap();
        let summary = |verb: &str, kind: &str, ns: &str, n: &str| format!("{verb} {kind} {ns}/{n}");
        assert_eq!(
            got.actions
                .iter()
                .map(|a| summary(&a.verb, &a.kind, &a.namespace, &a.name))
                .collect::<Vec<_>>(),
            want_actions
                .iter()
                .map(|a| summary(
                    a["verb"].as_str().unwrap(),
                    a["kind"].as_str().unwrap(),
                    a["namespace"].as_str().unwrap(),
                    a["name"].as_str().unwrap()
                ))
                .collect::<Vec<_>>(),
            "{ctx}: actions"
        );
        for (i, (g, w)) in got.actions.iter().zip(want_actions).enumerate() {
            let w_obj = w.get("object").cloned();
            assert_eq!(
                g.object, w_obj,
                "{ctx}: action #{i} ({} {} {}) body",
                g.verb, g.kind, g.name
            );
        }

        assert_eq!(
            got.exists,
            want["exists"].as_bool().unwrap(),
            "{ctx}: exists"
        );
        assert_eq!(got.status, want.get("status").cloned(), "{ctx}: status");
        let want_finalizers: Vec<String> =
            serde_json::from_value(want["finalizers"].clone()).unwrap();
        assert_eq!(got.finalizers, want_finalizers, "{ctx}: finalizers");
    }
}

