#[tokio::test]
async fn lifecycle() {
    let mut objs = world();
    objs.push(obj(&base_cr()));
    let e = new_env(objs);
    let mut s = vec![];
    s.push(e.reconcile("add finalizer", key()).await);
    s.push(e.reconcile("initial provisioning", key()).await);
    s.push(e.reconcile("waiting for control plane", key()).await);

    e.mutate_hc_status(|hc| {
        hc.status.conditions = hc_conditions(CONDITION_TRUE);
        hc.status.control_plane_version.history = history(&[("4.19.0", IMAGE_419)]);
    })
    .await;
    e.create(kubeconfig_secret()).await;
    s.push(
        e.reconcile("hc available, kubeconfig injected", key())
            .await,
    );
    s.push(e.reconcile("generating ignition fails", key()).await);
    s.push(e.reconcile("ignition retry after failure", key()).await);

    e.create(ignition_cm("flavor-1", "bfb-1")).await;
    e.mutate_cr_status(ignition_configured_true).await;
    s.push(e.reconcile("ignition configured", key()).await);
    s.push(e.reconcile("ready steady state", key()).await);

    e.mutate_dd(|dd| dd.spec.dpus.bfb = Some("bfb-2".into()))
        .await;
    s.push(e.reconcile("bfb changed", key()).await);
    s.push(e.reconcile("after bfb change", key()).await);

    e.create(dpu_flavor("flavor-2")).await;
    e.mutate_dd(|dd| dd.spec.dpus.flavor = Some("flavor-2".into()))
        .await;
    s.push(e.reconcile("flavor changed", key()).await);
    s.push(e.reconcile("regenerate after flavor change", key()).await);

    // simulate a successful regeneration, then upgrade the release image
    e.create(ignition_cm("flavor-2", "bfb-2")).await;
    e.mutate_cr_status(ignition_configured_true).await;
    s.push(e.reconcile("ready again", key()).await);
    e.mutate_cr(|cr| {
        cr.spec.ocp_release_image = IMAGE_420.into();
        cr.metadata.generation = Some(2);
    })
    .await;
    s.push(e.reconcile("upgrade detected", key()).await);
    s.push(e.reconcile("upgrade in progress", key()).await);
    e.mutate_hc_status(|hc| {
        hc.status.control_plane_version.history =
            history(&[("4.20.0", IMAGE_420), ("4.19.0", IMAGE_419)]);
    })
    .await;
    s.push(e.reconcile("upgrade complete", key()).await);
    s.push(e.reconcile("after upgrade", key()).await);

    e.delete(base_cr()).await;
    for i in 1..=4 {
        s.push(e.reconcile(&format!("deletion {i}"), key()).await);
    }
    check("lifecycle", &s);
}

