#[tokio::test]
async fn hc_blocked() {
    let e = ready_world(vec![]);
    e.mutate_hc_status(|hc| {
        hc.status.conditions = vec![
            cond_now(
                hyperv1::HOSTED_CLUSTER_AVAILABLE,
                CONDITION_FALSE,
                "WaitingForAvailable",
                "failed to extract release metadata",
            ),
            cond_now(
                hyperv1::HOSTED_CLUSTER_PROGRESSING,
                CONDITION_FALSE,
                hyperv1::BLOCKED_REASON,
                "failed to extract release metadata",
            ),
        ];
    })
    .await;
    let mut s = vec![e.reconcile("hc blocked", key()).await];
    e.mutate_hc_status(|hc| {
        hc.status.conditions = vec![
            cond_now(
                hyperv1::HOSTED_CLUSTER_AVAILABLE,
                CONDITION_TRUE,
                "AsExpected",
                "available",
            ),
            cond_now(
                hyperv1::HOSTED_CLUSTER_DEGRADED,
                CONDITION_TRUE,
                "DegradedError",
                "errors requiring intervention",
            ),
        ];
    })
    .await;
    s.push(e.reconcile("hc degraded", key()).await);
    check("hc_blocked", &s);
}

#[tokio::test]
async fn upgrade_recovery() {
    let mut cr = ready_cr();
    cr.spec.ocp_release_image = IMAGE_420.into();
    cr.metadata.generation = Some(2);
    let hc = owned_hc(IMAGE_420);
    let mut np = hyperv1::NodePool {
        metadata: ObjectMeta {
            owner_references: Some(owner_refs()),
            ..om(CR_NAME, CR_NS)
        },
        ..Default::default()
    };
    np.spec.cluster_name = CR_NAME.into();
    np.spec.release.image = IMAGE_419.into();
    let mut objs = world();
    objs.extend([
        obj(&cr),
        obj(&hc),
        obj(&np),
        obj(&kubeconfig_secret()),
        obj(&ignition_cm("flavor-1", "bfb-1")),
    ]);
    let e = new_env(objs);
    let s = vec![
        e.reconcile("recover missed upgrade", key()).await,
        e.reconcile("upgrade in progress", key()).await,
    ];
    check("upgrade_recovery", &s);
}
